<?php session_start();require_once __DIR__."/../conn.php";require_once __DIR__."/../auth.php";require_once __DIR__."/../sort_utils.php";requireStaff();
$allowed=['f.furniture_name'=>'Furniture','f.price'=>'Price','oc'=>'Orders','tq'=>'Qty Sold','ts'=>'Total Sales'];list($sort,$order)=get_sort_params($allowed,'ts');
$sql="SELECT f.furniture_id,f.furniture_name,f.price,COUNT(o.order_id) as oc,COALESCE(SUM(o.order_quantity),0) as tq,COALESCE(SUM(o.total_amount),0) as ts FROM Furniture f LEFT JOIN Orders o ON f.furniture_id=o.furniture_id GROUP BY f.furniture_id ".sort_clause($sort,$order);
$r=mysqli_query($conn,$sql);$rep=array();while($rw=mysqli_fetch_assoc($r))$rep[]=$rw;mysqli_free_result($r);
$gt=mysqli_fetch_row(mysqli_query($conn,"SELECT COALESCE(SUM(total_amount),0) FROM Orders"))[0];
$to=mysqli_fetch_row(mysqli_query($conn,"SELECT COUNT(*) FROM Orders"))[0];
$tq=mysqli_fetch_row(mysqli_query($conn,"SELECT COALESCE(SUM(order_quantity),0) FROM Orders"))[0];mysqli_close($conn);
?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Reports</title><link rel="stylesheet" href="style.css">
