<body><div id="sidebar-container"></div><div class="mc"><div class="top-bar"><div class="page-title">Reports Center</div></div><div style="padding:24px 32px">
<div class="sum"><div class="sc"><div class="sn"><?php echo $to;?></div><div class="sl">Total Orders</div></div><div class="sc"><div class="sn"><?php echo $tq;?></div><div class="sl">Items Sold</div></div><div class="sc"><div class="sn">$<?php echo number_format($gt,2);?></div><div class="sl">Total Revenue</div></div></div>
<h2 style="margin:24px 0 16px;font-weight:500;">Sales by Furniture</h2>
<div class="tw"><table><thead><tr><th><?php echo sortable_th('f.furniture_name','Furniture',$sort,$order);?></th><th><?php echo sortable_th('f.price','Price',$sort,$order);?></th><th><?php echo sortable_th('oc','Orders',$sort,$order);?></th><th><?php echo sortable_th('tq','Qty Sold',$sort,$order);?></th><th><?php echo sortable_th('ts','Total Sales',$sort,$order);?></th></tr></thead><tbody>
<?php foreach($rep as $rw):?><tr><td><strong><?php echo htmlspecialchars($rw["furniture_name"]);?></strong></td><td>$<?php echo number_format($rw["price"],2);?></td><td><?php echo $rw["oc"]?:0;?></td><td><?php echo $rw["tq"]?:0;?></td><td><strong><?php echo $rw["ts"]?"$".number_format($rw["ts"],2):"-";?></strong></td></tr><?php endforeach;?></tbody></table></div></div></div>
